// prooflift.rs — the closure-reads-a-proof verdicts, on the metal.
//
// The manuscript's verdicts were obtained on a host: a lifter walked Lean proof
// terms into the twelve and a binary returned the verdict. That is a transcript,
// and a transcript has to be trusted. This module carries the WORDS and asks the
// ON-BOARD kernel — the same `check::word_verdict` that gates the vita trunk's
// speech — so the result can be booted rather than believed.
//
// The words are lifted proof terms. A recursor opens the fork, its branches are
// the arms, the rejoin is the fuse, an application composes, a bound variable is
// identity, and the axiom of unproved assertion opens a fork with nothing to pair
// it. That last is why an undischarged claim reads B here: not by a rule added
// for proofs, but by the rule already present for a branch that never reconverges.

use alloc::string::{String, ToString};
use alloc::format;
use alloc::vec::Vec;
use imasm_core::check;
use imasm_core::classic::Token as CTok;

/// `p -> p` proved by the hypothesis: no fork anywhere.
pub const IDENTITY: &str = "⊢⊙⊣";
/// A case analysis with both branches discharged.
pub const CLOSED_FORK: &str = "⊢∈⊤⊙⊥⊙⊥⊡⋈⊙⋈⊙⊥⊙⊥⊡⋈⊙⋈⊙⋈⊙⊥⊡⋈⊙⋈⊙⋈⊙⊥⊡⋈⊡⋈⊙⋈⊙⋈⊙∋⊣";
/// The same, one branch left undischarged.
pub const OPEN_FORK: &str = "⊢∈⊤⊙⊥⊙⊥⊡⋈⊙⋈⊙⊥⊙⊥⊡⋈⊙⋈⊙⋈⊙⊥∈⊥⊡⋈⊡⋈⊙⋈⊙⋈⊙∋⊣";
/// A development that is nothing but an undischarged claim.
pub const ALL_SORRY: &str = "⊢∈⊣";
/// The proof of mu-after-delta = id: the object stating what this kernel
