fn verdict_of(word: &str) -> char {
    let toks: Vec<CTok> = word.chars().filter_map(|c| CTok::parse(&c.to_string())).collect();
    check::word_verdict(&toks).0
}

/// The four calibration words. Cheap: none exceeds a few dozen tokens.
pub fn report() -> String {
    let mut s = String::new();
    s.push_str("=== PROOFLIFT — proof terms judged by the on-board kernel ===\n\n");
    s.push_str("A proof term is a graph. A case analysis is the fork, the branches\n");
    s.push_str("landing on one goal is the fuse, an undischarged claim is a fork with\n");
    s.push_str("nothing to pair it. No rule was added for proofs; these are the verdicts\n");
    s.push_str("this kernel already returns for compiled control flow.\n\n");

    let rows: [(&str, &str, &str); 4] = [
        ("identity  p -> p", IDENTITY, "no fork: nothing weighed"),
        ("case split, discharged", CLOSED_FORK, "fork, work, fuse"),
        ("one branch undischarged", OPEN_FORK, "a fork left open"),
        ("nothing but a claim", ALL_SORRY, "the claim, never rejoined"),
    ];
    for (name, word, gloss) in rows.iter() {
        let v = verdict_of(word);
        s.push_str(&format!("  {:<24} {}   {:>6} glyphs   {}\n",
                            name, v, word.chars().count(), gloss));
    }
    s.push_str("\nExpected: N T B B.\n");
    s.push_str("`prooflift nest` runs the self-nest word — the proof of mu.delta = id\n");
    s.push_str("itself, tens of thousands of tokens. It returns T, in seconds.\n");
    s.push_str("An undischarged claim and an unrejoined fork are one object, and this\n");
    s.push_str("kernel was not told about proofs in order to see it.\n");
    s
}

/// The nest: the closure law's own proof, judged by this kernel.
///
/// Kept separate because the word is tens of thousands of tokens and the walk is
/// still the expensive one. It used not to return at all: `successors` scanned
/// the whole edge list and allocated on every call, inside the inner loop of a
/// DFS run once per fork. With adjacency built once it returns in seconds.
pub fn nest() -> String {
    let n = SELF_NEST.chars().count();
    let v = verdict_of(SELF_NEST);
    format!("=== THE NEST ===\n\n  proof of mu.delta = id   {} glyphs   verdict {}\n\n\
             The object stating what this kernel computes, handed to this kernel.\n", n, v)
}
